    {
      "type": 1,
      "content": {
        "json": "# Azure Functions - issues and retirement readiness\r\n\r\nFleet-wide view of Azure Function App problems using Azure Resource Graph, with\r\non-demand ARM runtime details. Includes dedicated tracking for the **Linux Consumption plan retirement\r\n(30 September 2028)**."
      },
      "name": "title"
    },
    {
      "type": 9,
      "content": {
        "version": "KqlParameterItem/1.0",
        "crossComponentResources": [
          "{Subscriptions}"
