            "content": {
              "version": "KqlItem/1.0",
              "query": "healthresources\n| where type =~ 'microsoft.resourcehealth/availabilitystatuses'\n| extend targetId = tolower(tostring(properties.targetResourceId))\n| join kind=inner (\n    resources\n| where type =~ 'microsoft.web/sites'\n| where kind contains 'functionapp'\n| where kind !contains 'workflowapp'\n    | extend _rgs = dynamic([{ResourceGroups}])\n| where array_length(_rgs) == 0 or set_has_element(_rgs, '*') or set_has_element(_rgs, resourceGroup)\n    | extend _apps = dynamic([{FunctionApps}])\n| where array_length(_apps) == 0 or set_has_element(_apps, '*') or set_has_element(_apps, tolower(id))\n    | join kind=leftouter (\n    resourcecontainers\n    | where type =~ 'microsoft.resources/subscriptions'\n    | project subscriptionId, Subscription = name\n  ) on subscriptionId\n    | project targetId = tolower(id), appName = name, appSubscription = Subscription, appSubscriptionId = subscriptionId, appRg = resourceGroup\n  ) on targetId\n| project\n    ['Function app'] = appName,\n    Subscription = appSubscription,\n    ['Subscription ID'] = appSubscriptionId,\n    ['Resource group'] = appRg,\n    Availability = tostring(properties.availabilityState),\n    Summary = tostring(properties.summary),\n    ['Since'] = todatetime(properties.occurredTime),\n    ResourceId = targetId\n| order by Availability asc",
              "size": 2,
              "title": "Resource health records available in Resource Graph",
              "queryType": 1,
              "resourceType": "microsoft.resourcegraph/resources",
              "crossComponentResources": [
                "{Subscriptions}"
