                  "label": "Function app for Resource Health",
                  "isRequired": true,
                  "query": "resources\n| where type =~ 'microsoft.web/sites'\n| where kind contains 'functionapp'\n| where kind !contains 'workflowapp'\n| extend _rgs = dynamic([{ResourceGroups}])\n| where array_length(_rgs) == 0 or set_has_element(_rgs, '*') or set_has_element(_rgs, resourceGroup)\n| extend _apps = dynamic([{FunctionApps}])\n| where array_length(_apps) == 0 or set_has_element(_apps, '*') or set_has_element(_apps, tolower(id))\n| order by name asc, id asc\n| extend n = row_number()\n| project value = id, label = strcat(name, ' [', resourceGroup, ']'), selected = (n == 1)",
                  "version": "KqlParameterItem/1.0"
