                  "id": "health-context",
                  "queryType": 1,
                  "version": "KqlParameterItem/1.0",
                  "isHiddenWhenLocked": true,
                  "name": "HealthContext",
                  "query": "resources\n| where type =~ 'microsoft.web/sites'\n| where kind contains 'functionapp'\n| where kind !contains 'workflowapp'\n| extend _rgs = dynamic([{ResourceGroups}])\n| where array_length(_rgs) == 0 or set_has_element(_rgs, '*') or set_has_element(_rgs, resourceGroup)\n| extend _apps = dynamic([{FunctionApps}])\n| where array_length(_apps) == 0 or set_has_element(_apps, '*') or set_has_element(_apps, tolower(id))\n| extend planId    = tolower(tostring(properties.serverFarmId))\n| extend tier      = tostring(properties.sku)\n| extend isLinux   = tobool(properties.reserved)\n| extend osType    = case(isLinux == true or kind contains 'linux', 'Linux', isLinux == false or kind contains 'windows', 'Windows', 'Unknown')\n| extend state     = tostring(properties.state)\n| extend enabledFlag = tobool(properties.enabled)\n| extend httpsOnly = tobool(properties.httpsOnly)\n| extend pna       = tostring(properties.publicNetworkAccess)\n| extend subnetId  = tostring(properties.virtualNetworkSubnetId)\n| extend availability = tostring(properties.availabilityState)\n| extend usage     = tostring(properties.usageState)\n| extend identityType = tostring(identity.type)\n| extend clientCert = tobool(properties.clientCertEnabled)\n| extend clientCertMode = tostring(properties.clientCertMode)\n| extend defaultHost = tostring(properties.defaultHostName)\n| extend memQuota  = toint(properties.dailyMemoryTimeQuota)\n| extend redundancy = tostring(properties.redundancyMode)\n| extend lastModified = todatetime(properties.lastModifiedTimeUtc)\n| extend alwaysOn  = tobool(properties.siteConfig.alwaysOn)\n| extend http2     = tobool(properties.siteConfig.http20Enabled)\n| extend flexRuntimeName = tostring(properties.functionAppConfig.runtime.name),\n    flexRuntimeVersion = tostring(properties.functionAppConfig.runtime.version),\n    linuxFx = tostring(properties.siteConfig.linuxFxVersion),\n    windowsFx = tostring(properties.siteConfig.windowsFxVersion)\n| extend RuntimeStack = case(\n    isnotempty(flexRuntimeName), strcat(flexRuntimeName, iff(isempty(flexRuntimeVersion), '', strcat('|', flexRuntimeVersion))),\n    isnotempty(linuxFx), linuxFx,\n    windowsFx)\n| extend RuntimeSource = case(\n    isnotempty(flexRuntimeName), 'functionAppConfig.runtime',\n    isnotempty(linuxFx), 'siteConfig.linuxFxVersion',\n    isnotempty(windowsFx), 'siteConfig.windowsFxVersion',\n    '')\n| extend Language = case(\n    isnotempty(flexRuntimeName), flexRuntimeName,\n    RuntimeStack startswith 'DOCKER|', '',\n    tostring(split(RuntimeStack, '|')[0])),\n    LangVersion = case(\n    isnotempty(flexRuntimeName), flexRuntimeVersion,\n    RuntimeStack startswith 'DOCKER|', '',\n    RuntimeStack contains '|', tostring(split(RuntimeStack, '|')[1]),\n    '')\n| extend scaleLimit = coalesce(toint(properties.functionAppConfig.scaleAndConcurrency.maximumInstanceCount),\n    toint(properties.siteConfig.functionAppScaleLimit))\n| join kind=leftouter (\n    resources\n    | where type =~ 'microsoft.web/serverfarms'\n    | project planId = tolower(id),\n              planName = name,\n              planSkuName = tostring(sku.name),\n              planSkuTier = tostring(sku.tier),\n              planCapacity = toint(sku.capacity),\n              planZoneRedundant = tobool(properties.zoneRedundant)\n  ) on planId\n| join kind=leftouter (\n    resourcecontainers\n    | where type =~ 'microsoft.resources/subscriptions'\n    | project subscriptionId, Subscription = name\n  ) on subscriptionId\n| extend tier = coalesce(tier, planSkuTier)\n| extend isConsumption = (tier =~ 'Dynamic'), isFlex = (tier =~ 'FlexConsumption'), isPremium = (tier =~ 'ElasticPremium')\n| extend isServerless = (isConsumption or isFlex), isDedicated = (isnotempty(tier) and not(isConsumption or isFlex or isPremium))\n| extend TierLabel = case(\n      isConsumption, 'Consumption (Y1)', isFlex, 'Flex Consumption',\n      isPremium, 'Premium (Elastic)', isempty(tier), 'Unknown', tier)\n| extend isLinuxConsumption = (isConsumption and osType == 'Linux')\n| extend SkuDisplay = strcat(coalesce(planSkuTier, tier), iff(isnotempty(planSkuName), strcat(' (', planSkuName, ')'), ''))\n| where id =~ '{HealthApp}'\n| summarize Apps = make_list(pack('id', id, 'name', name, 'subscription', Subscription, 'subscriptionId', subscriptionId,\n    'resourceGroup', resourceGroup, 'os', osType, 'isFlex', isFlex, 'stack', RuntimeStack), 2)\n| extend App = iff(array_length(Apps) == 1, Apps[0], dynamic({}))\n| project value = tostring(pack('status', iff(array_length(Apps) == 1, 'ready', 'Select one Function App within the current filters.'),\n    'app', App)), selected = true",
                  "resourceType": "microsoft.resourcegraph/resources"
