                    "query": "{\"version\":\"ARMEndpoint/1.0\",\"batchDisabled\":true,\"urlParams\":[{\"value\":\"2025-05-01\",\"key\":\"api-version\"}],\"method\":\"GET\",\"path\":\"{HealthContext:$.app.id}/providers/Microsoft.ResourceHealth/availabilityStatuses/current\",\"headers\":[],\"transformers\":[{\"type\":\"jsonpath\",\"settings\":{\"columns\":[{\"substringRegexMatch\":\"^.*$\",\"substringReplace\":\"{HealthContext:$.app.name}\",\"columnType\":\"string\",\"columnid\":\"Function app\",\"path\":\"$.id\"},{\"substringRegexMatch\":\"^.*$\",\"substringReplace\":\"{HealthContext:$.app.subscription}\",\"columnType\":\"string\",\"columnid\":\"Subscription\",\"path\":\"$.id\"},{\"substringRegexMatch\":\"^.*$\",\"substringReplace\":\"{HealthContext:$.app.subscriptionId}\",\"columnType\":\"string\",\"columnid\":\"Subscription ID\",\"path\":\"$.id\"},{\"substringRegexMatch\":\"^.*$\",\"substringReplace\":\"{HealthContext:$.app.resourceGroup}\",\"columnType\":\"string\",\"columnid\":\"Resource group\",\"path\":\"$.id\"},{\"columnType\":\"string\",\"columnid\":\"Availability\",\"path\":\"$.properties.availabilityState\"},{\"columnType\":\"string\",\"columnid\":\"Summary\",\"path\":\"$.properties.summary\"},{\"columnType\":\"string\",\"columnid\":\"Reason\",\"path\":\"$.properties.reasonType\"},{\"columnType\":\"datetime\",\"columnid\":\"Last change\",\"path\":\"$.properties.occuredTime\"},{\"columnType\":\"datetime\",\"columnid\":\"Last checked\",\"path\":\"$.properties.reportedTime\"}],\"tablePath\":\"$\"}}]}",
